package com.aaliyun.leadnews.article.service;
import com.aaliyun.leadnews.article.config.MinioProperties;import com.aaliyun.leadnews.article.domain.Article;import com.aaliyun.leadnews.model.foundation.ArticleContentItemDTO;import freemarker.template.Configuration;import org.junit.jupiter.api.Test;import java.time.LocalDateTime;import java.util.List;import static org.assertj.core.api.Assertions.assertThat;
class ArticleHtmlRendererTest{@Test void rendersImagesAndEscapesText()throws Exception{Configuration c=new Configuration(Configuration.VERSION_2_3_34);c.setClassLoaderForTemplateLoading(getClass().getClassLoader(),"templates");Article a=new Article();a.setTitle("<标题>");a.setAuthorName("author");a.setChannelName("tech");a.setPublishTime(LocalDateTime.of(2026,1,2,3,4));String html=new ArticleHtmlRenderer(c).render(a,List.of(new ArticleContentItemDTO("text","<script>alert(1)</script>"),new ArticleContentItemDTO("image","https://example.test/a.jpg")));assertThat(html).contains("&lt;标题&gt;").contains("&lt;script&gt;alert(1)&lt;/script&gt;").contains("<img src=\"https://example.test/a.jpg\"");}
 @Test void objectKeyIsDeterministic(){ArticleObjectStorage s=new ArticleObjectStorage(null,new MinioProperties("http://localhost","http://localhost","a","b","leadnews"));assertThat(s.key(123)).isEqualTo("article/123/index.html");assertThat(s.key(123)).isEqualTo(s.key(123));}}
